    const rDb = loadRewardsDatabase();
    const claim = rDb.claims.find((c) => c.claimId === id || c.id === id);
    if (!claim) {
      return res.status(404).json({ error: "\u0915\u094D\u0932\u0947\u092E \u0928\u0939\u0940\u0902 \u092E\u093F\u0932\u093E" });
    }
