      if (href === source.url || href.endsWith("/entertainment") || href.endsWith("/madhya-pradesh")) continue;
      const pathPart = (() => {
        try {
          return new URL(href).pathname;
        } catch {
          return "";
        }
      })();
      if (pathPart.length < 18 || !/[-/]\d{4,}|[-][a-z0-9]{4,}/i.test(pathPart)) continue;
