    const isVipTier = tier === "ultra" || tier === "vip" || tier === "vip_desk";
    const maxAllowed = planDetail?.maxGraphicsPerDay !== void 0 ? planDetail.maxGraphicsPerDay : isVipTier ? 75 : tier === "professional" ? 40 : tier === "advanced" ? 25 : 10;
